UPDATE warning w SET timezone = (
    SELECT concat('UTC',
          CASE WHEN (EXTRACT(epoch FROM tn.utc_offset)/3600) > -1
               THEN concat('+', cast(cast(EXTRACT(epoch FROM tn.utc_offset)/3600 as real) as varchar))
               ELSE cast(cast(EXTRACT(epoch FROM tn.utc_offset)/3600 as real) AS varchar)
          END
    )
    FROM pg_timezone_names tn
    WHERE tn.name = w.timezone
);

UPDATE georegulation gr SET timezone = (
    SELECT concat('UTC',
          CASE WHEN (EXTRACT(epoch FROM tn.utc_offset)/3600) > -1
                   THEN concat('+', cast(cast(EXTRACT(epoch FROM tn.utc_offset)/3600 as real) as varchar))
               ELSE cast(cast(EXTRACT(epoch FROM tn.utc_offset)/3600 as real) AS varchar)
              END
       )
    FROM pg_timezone_names tn
    WHERE tn.name = gr.timezone
);

UPDATE infosource i SET timezone = (
    SELECT concat('UTC',
          CASE WHEN (EXTRACT(epoch FROM tn.utc_offset)/3600) > -1
                   THEN concat('+', cast(cast(EXTRACT(epoch FROM tn.utc_offset)/3600 as real) as varchar))
               ELSE cast(EXTRACT(epoch FROM tn.utc_offset)/3600 AS varchar)
          END
    )
    FROM pg_timezone_names tn
    WHERE tn.name = i.timezone
);

CREATE OR REPLACE FUNCTION get_an (_nameOfSerie VARCHAR, _lang TEXT) RETURNS TABLE ( warningId uuid, warningType VARCHAR, nameOfSeries VARCHAR, warningNumber INTEGER, year INTEGER, generalArea TEXT, locality TEXT, warningHazardTypeGeneral VARCHAR, publicationDate timestamp, cancellationDate timestamp, language TEXT, productionAgency VARCHAR, country VARCHAR, featurePartId uuid, featurePartPosition INTEGER, featurePartWarningHazardTypeDetails TEXT, featurePartInformation TEXT, featurePartDateRange TEXT, type TEXT, geom geometry ) AS $$
BEGIN
RETURN QUERY (select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct case _lang when 'fr' then w_locality.name else w_locality.international_name end, ',') as locality, w.warning_hazard_type_general as warningHazardTypeGeneral, w.publication_time as publicationDate, w.cancellation_date as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, string_agg(distinct part_type.warning_hazard_type_detail, ',') as featurePartWarningHazardTypeDetails, part_text.text as featurePartInformation, string_agg(concat(part_date.date_start, ' ', part_date.time_of_day_start, '/', part_date.date_end, ' ', part_date.time_of_day_end, ''), ',') as featurePartDateRange, 'geom' as type, part_geom.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality_names as w_locality on w.id=w_locality.warning_id left join warning_feature_part_geometry as part_geom on part_geom.feature_part_id=part.id left join warning_feature_part_warning_hazard_type_details as part_type on part_type.feature_part_id = part.id left join localized_text as part_text on part_text.parent_id=part.id and part_text.language=_lang left join fixed_date_range as part_date on part_date.parent_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part_type.warning_hazard_type_detail, part_text.text, part.position, part_geom.geom order by w.id ) UNION ( select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct case _lang when 'fr' then w_locality.name else w_locality.international_name end, ',') as locality, w.warning_hazard_type_general as warningHazardType, w.publication_time as publicationDate, w.cancellation_date as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, string_agg(distinct part_type.warning_hazard_type_detail, ',') as featurePartWarningType, part_text.text as featurePartInformation, string_agg(concat(part_date.date_start, ' ', part_date.time_of_day_start, '/', part_date.date_end, ' ', part_date.time_of_day_end, ''), ',') as featurePartDateRange, 'affected_area' as type, part_affectedarea.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality_names as w_locality on w.id=w_locality.warning_id inner join warning_feature_part_affected_area as part_affectedarea on part_affectedarea.feature_part_id=part.id left join warning_feature_part_warning_hazard_type_details as part_type on part_type.feature_part_id = part.id left join localized_text as part_text on part_text.parent_id=part.id and part_text.language=_lang left join fixed_date_range as part_date on part_date.parent_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part_type.warning_hazard_type_detail, part_text.text, part.position, part_affectedarea.geom order by w.id ); END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION convert_utc(utc varchar)
    RETURNS varchar AS $$
DECLARE
    sign varchar;
    hours integer;
    minutes integer;
BEGIN
    sign := substring(utc from 4 for 1);
    hours := floor(cast(substring(utc from 5) as numeric));
    minutes := (cast(substring(utc from 5) as numeric) - hours) * 60;
    RETURN 'UTC' || sign || to_char(hours, 'FM00') || ':' || to_char(minutes, 'FM00');
END; $$
LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION format_date_to_string(dateParam DATE, timeParam TIME, timezoneParam VARCHAR)
    RETURNS varchar AS $$
BEGIN
    RETURN to_char(((to_char(dateParam, 'YYYY-MM-DD') || ' ' || to_char(timeParam, 'HH24:MI:SS'))::timestamp at time zone 'UTC' at time zone convert_utc(timezoneParam))::timestamp, 'YYYY-MM-DD HH24:MI:SS');
END; $$
LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION format_date_or_time(dateParam DATE, timeParam TIME, timezoneParam VARCHAR)
    RETURNS timestamp AS $$
DECLARE
    _serverUtcOffset INTERVAL := '1 hour';
BEGIN
    RETURN ((to_char(dateParam, 'YYYY-MM-DD') || ' ' || to_char(timeParam + _serverUtcOffset, 'HH24:MI:SS'))::timestamp at time zone 'UTC' at time zone convert_utc(timezoneParam))::timestamp;
END; $$
LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_anpart_info (_warningId uuid, _lang TEXT, _defaultLang TEXT, _partPosition INTEGER) RETURNS TABLE ( featurePartId uuid, featurePartWarningHazardTypeDetails TEXT, featurePartInformation TEXT, featurePartDateRange jsonb ) AS $$
BEGIN
RETURN QUERY (select distinct part.id as featurePartId, case _lang when 'fr' THEN string_agg(distinct type_details.translation, ',') when 'en' THEN string_agg(distinct type_details.international_translation, ',') end featurePartWarningHazardTypeDetails, case when (part_text.text is not null) THEN part_text.text ELSE default_part_text.text END as featurePartInformation, to_jsonb(json_agg(distinct get_feature_part_date_range(part_date.position, part_date.date_start, part_date.time_of_day_start, part_date.date_end, part_date.time_of_day_end, part_date.timezone))) as featurePartDateRange from warning_feature_part as part left join warning as w on part.warning_id=w.id left join warning_feature_part_warning_hazard_type_details as part_type on part_type.feature_part_id = part.id left join localized_text as part_text on part_text.parent_id=part.id and part_text.language=_lang left join localized_text as default_part_text on default_part_text.parent_id=part.id and default_part_text.language=_defaultLang left join fixed_date_range as part_date on part_date.parent_id=part.id left join warning_hazard_type_details as type_details on type_details.enum_name=part_type.warning_hazard_type_detail where w.id = _warningId and part.position=_partPosition group by w.id, part.id, featurePartInformation ); END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_an_with_allinfoparts (_lang TEXT, _defaultLang TEXT = 'fr') RETURNS TABLE ( warningId uuid, warningType VARCHAR, nameOfSeries VARCHAR, warningNumber INTEGER, year INTEGER, generalArea TEXT, locality TEXT, warningHazardTypeGeneral TEXT, publicationDate TEXT, cancellationDate TEXT, language TEXT, productionAgency VARCHAR, country VARCHAR, featurePartId uuid, featurePartPosition INTEGER, parts jsonb, cancelledWarnings jsonb, type TEXT, geom geometry ) AS $$
BEGIN
RETURN QUERY (select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct case _lang when 'fr' then w_locality.name else w_locality.international_name end, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'geom' as type, part_geom.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality_names as w_locality on w.id=w_locality.warning_id left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general left join warning_feature_part_geometry as part_geom on part_geom.feature_part_id=part.id where w.status='PUBLISHED' group by w.id, s.type, part.id, part.position, part_geom.geom order by w.id ) UNION ( select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct case _lang when 'fr' then w_locality.name else w_locality.international_name end, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'affected_area' as type, part_affectedarea.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality_names as w_locality on w.id=w_locality.warning_id left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general inner join warning_feature_part_affected_area as part_affectedarea on part_affectedarea.feature_part_id=part.id where w.status='PUBLISHED' group by w.id, s.type, part.id, part.position, part_affectedarea.geom order by w.id ); END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION get_an_with_allinfoparts_for_serie (_nameOfSerie VARCHAR, _lang TEXT, _defaultLang TEXT = 'fr') RETURNS TABLE ( warningId uuid, warningType VARCHAR, nameOfSeries VARCHAR, warningNumber INTEGER, year INTEGER, generalArea TEXT, locality TEXT, warningHazardTypeGeneral TEXT, publicationDate TEXT, cancellationDate TEXT, language TEXT, productionAgency VARCHAR, country VARCHAR, featurePartId uuid, featurePartPosition INTEGER, parts jsonb, cancelledWarnings jsonb, type TEXT, geom geometry ) AS $$
BEGIN
RETURN QUERY (select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct case _lang when 'fr' then w_locality.name else w_locality.international_name end, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'geom' as type, part_geom.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality_names as w_locality on w.id=w_locality.warning_id left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general left join warning_feature_part_geometry as part_geom on part_geom.feature_part_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part.position, part_geom.geom order by w.id ) UNION ( select distinct w.id as warningId, s.type as warningType, w.name_of_series as nameOfSeries, w.warning_number as warningNumber, w.year as year, string_agg(distinct w_area.name, ',') as generalArea, string_agg(distinct case _lang when 'fr' then w_locality.name else w_locality.international_name end, ',') as locality, case _lang when 'fr' THEN string_agg(distinct type_general.translation, ',') when 'en' THEN string_agg(distinct type_general.international_translation, ',') end warningHazardTypeGeneral, to_char(w.publication_time, 'DD/MM/YYYY') as publicationDate, to_char(w.cancellation_date, 'DD/MM/YYYY HH24:MI:SS TZ') as cancellationDate, _lang as "language", w.production_agency as productionAgency, w.country as country, part.id as featurePartId, part.position as featurePartPosition, (select get_anpart_infos(w.id, _lang, _defaultLang)) as parts, (select get_an_cancelled(w.id) as cancelledWarnings), 'affected_area' as type, part_affectedarea.geom as geom from warning_feature_part as part left join warning as w on part.warning_id=w.id left join serie as s on w.serie_id=s.id left join warning_general_area as w_area on w.id=w_area.warning_id left join warning_locality_names as w_locality on w.id=w_locality.warning_id left join warning_hazard_type_general as type_general on type_general.enum_name=w.warning_hazard_type_general inner join warning_feature_part_affected_area as part_affectedarea on part_affectedarea.feature_part_id=part.id where w.status='PUBLISHED' and UPPER(w.name_of_series)=UPPER(_nameOfSerie) group by w.id, s.type, part.id, part.position, part_affectedarea.geom order by w.id ); END; $$ LANGUAGE 'plpgsql';

CREATE OR REPLACE FUNCTION format_date_range_from_utc_to_timezone(dateParam DATE, timeParam TIME, timezoneParam VARCHAR)
    RETURNS timestamp AS $$
BEGIN
RETURN ((to_char(dateParam, 'YYYY-MM-DD') || ' ' || to_char(timeParam, 'HH24:MI:SS'))::timestamp at time zone convert_utc(timezoneParam) at time zone 'UTC')::timestamp;
END; $$
LANGUAGE 'plpgsql';
